#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>

int main() {
    std::vector<int> c1 = {1, 3, 5, 7};
    std::vector<int> c2 = {2, 3, 6, 7, 8};
    std::vector<int> result;
    result.reserve(c1.size() + c2.size());

    // Perform set union of c1 and c2 into result
    std::set_union(c1.begin(), c1.end(), c2.begin(), c2.end(),
                   std::back_inserter(result));

    // Output the result elements separated by spaces
    std::copy(result.begin(), result.end(), std::ostream_iterator<int>(std::cout, " "));
    std::cout << std::endl;
    return 0;
}
